<template><view class="page"><view class="nav"><text @click="back">‹</text><text>代理管理</text><text @click="load">⟳</text></view><view class="card"><text class="title">代理状态</text><text>{{ JSON.stringify(status, null, 2) }}</text><button @click="doHealth">健康检查</button><button @click="doReload">重载配置</button></view></view></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { getStatus,healthCheck,reload } from '@/api/proxy';const status=ref<any>({});async function load(){try{status.value=await getStatus()}catch(e:any){uni.showToast({title:e?.message||'加载失败',icon:'none'})}}async function doHealth(){try{status.value=await healthCheck();uni.showToast({title:'检查完成',icon:'success'})}catch(e:any){uni.showToast({title:e?.message||'检查失败',icon:'none'})}}async function doReload(){try{await reload();uni.showToast({title:'已重载',icon:'success'});load()}catch(e:any){uni.showToast({title:e?.message||'重载失败',icon:'none'})}}function back(){uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/index'})})}onMounted(load)</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f5f7}.nav{height:88rpx;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;font-size:32rpx;font-weight:700}.nav text:first-child{font-size:48rpx;color:#6b7280}.nav text:last-child{font-size:34rpx;color:#4f46e5}.card{margin:24rpx;background:#fff;border-radius:24rpx;padding:28rpx;display:flex;flex-direction:column;gap:18rpx}.title{font-size:30rpx;font-weight:700}button{height:72rpx;line-height:72rpx;border-radius:16rpx;background:#4f46e5;color:#fff}</style>
